using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CourseCatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CourseCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics including analysis, algebra, and statistics." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their impact on the modern world." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 50 papers and holds 3 patents in distributed database technology.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Mitchell", Title = "Associate Professor", Bio = "Dr. Mitchell's research focuses on algebraic topology and its applications. He received the University Teaching Excellence Award in 2023.", Email = "j.mitchell@university.edu" },
            new() { Id = 3, Name = "Dr. Maria Rodriguez", Title = "Professor", Bio = "Dr. Rodriguez is an expert in quantum mechanics and particle physics. She previously worked at CERN on the Large Hadron Collider project.", Email = "m.rodriguez@university.edu" },
            new() { Id = 4, Name = "Dr. David Park", Title = "Assistant Professor", Bio = "Dr. Park specializes in machine learning and artificial intelligence. His recent work focuses on natural language processing and transformer architectures.", Email = "d.park@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Watson", Title = "Professor", Bio = "Dr. Watson is a literary scholar specializing in Victorian literature and postcolonial studies. She has authored three books on narrative theory.", Email = "e.watson@university.edu" },
            new() { Id = 6, Name = "Dr. Robert Taylor", Title = "Associate Professor", Bio = "Dr. Taylor researches early modern European history with a focus on the Scientific Revolution and Enlightenment.", Email = "r.taylor@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Title = "Introduction to Programming", CourseCode = "CS 101", Description = "Fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", CourseCode = "CS 201", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithms (sorting, searching, dynamic programming). Prerequisite: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, InstructorId = 1, IsFeatured = false },
            new() { Id = 3, Title = "Machine Learning", CourseCode = "CS 401", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Prerequisite: CS 201, MATH 202.", Credits = 4, Schedule = "Mon/Wed 2:00–3:30 PM", DepartmentId = 1, InstructorId = 4, IsFeatured = true },
            new() { Id = 4, Title = "Calculus I", CourseCode = "MATH 101", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorId = 2, IsFeatured = false },
            new() { Id = 5, Title = "Linear Algebra", CourseCode = "MATH 202", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 6, Title = "Quantum Mechanics I", CourseCode = "PHYS 301", Description = "Introduction to quantum theory: wave-particle duality, Schrödinger equation, hydrogen atom, and angular momentum. Prerequisite: PHYS 201, MATH 202.", Credits = 4, Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 7, Title = "Classical Mechanics", CourseCode = "PHYS 201", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, and rigid body dynamics.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, InstructorId = 3, IsFeatured = false },
            new() { Id = 8, Title = "Creative Writing", CourseCode = "ENG 210", Description = "Workshop-based course in fiction and poetry writing. Students produce and critique original work in a supportive environment.", Credits = 3, Schedule = "Wed 3:00–5:30 PM", DepartmentId = 4, InstructorId = 5, IsFeatured = false },
            new() { Id = 9, Title = "World Literature", CourseCode = "ENG 150", Description = "Survey of major literary works from diverse global traditions. Explores themes of identity, migration, and cultural exchange.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", DepartmentId = 4, InstructorId = 5, IsFeatured = true },
            new() { Id = 10, Title = "Modern World History", CourseCode = "HIST 101", Description = "Global history from 1750 to the present. Major revolutions, industrialization, world wars, and decolonization.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, InstructorId = 6, IsFeatured = false }
        };

        // Link navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

